  ('thu-2026-11-16', 'sentence', 'Sở thích của tôi là nhạc, guitar, đi du lịch và đồ ăn.', 'Meine Hobbys sind Musik, Gitarre, Reisen und Essen.', '', '', '', '', '', '', 'gebildet von Jarvis', 77),
